import itertools

vertices = list(range(8))
fixed_edges = [(2,6), (0,6), (4,7), (6,7), (3,7)]

# All possible edges not already fixed
candidate_edges = [(u, v) for u in range(8) for v in range(u+1, 8) if (u, v) not in fixed_edges]

# We need to select a subset of candidate_edges such that each vertex gets enough additional degree
needed = {0: 2, 1: 3, 2: 2, 3: 2, 4: 2, 5: 3, 6: 0, 7: 0}

# Let's try to use pysat
try:
    from pysat import CNF, Solver
    from pysat.card import CardEnc

    cnf = CNF()

    # Variable for each candidate edge
    edge_var = {}
    for i, (u, v) in enumerate(candidate_edges):
        edge_var[(u, v)] = i + 1

    # For each vertex, we need at least 'needed' edges incident to it
    for v in range(8):
        if needed[v] == 0:
            continue
        incident_vars = []
        for (u, w), var in edge_var.items():
            if u == v or w == v:
                incident_vars.append(var)
        # At least needed[v] of these must be true
        cnf.extend(CardEnc.atleast(lits=incident_vars, bound=needed[v], topk=len(incident_vars)))

    solver = Solver(name='cadical153')
    solver.append_formula(cnf)

    if solver.solve():
        model = solver.get_model()
        selected_edges = []
        for (u, v), var in edge_var.items():
            if model[var - 1] > 0:
                selected_edges.append((u, v))
        print("Found solution!")
        print("Additional edges:", selected_edges)
        all_edges = fixed_edges + selected_edges
        print("All edges:", sorted(all_edges))

        # Verify degrees
        deg = {v: 0 for v in range(8)}
        for u, v in all_edges:
            deg[u] += 1
            deg[v] += 1
        print("Degrees:", deg)
        print("Min degree:", min(deg.values()))
    else:
        print("UNSATISFIABLE")
except ImportError:
    print("pysat not available, trying brute force")

    # Brute force with some pruning
    # We need exactly 7 edges (since sum needed = 14, each edge adds 2)
    # But we could also add more edges (degree > 3 is fine)
    # Let's try to find any solution

    from itertools import combinations

    found = False
    for r in range(7, len(candidate_edges) + 1):
        if found:
            break
        for combo in combinations(candidate_edges, r):
            deg = {v: 0 for v in range(8)}
            for u, v in fixed_edges:
                deg[u] += 1
                deg[v] += 1
            for u, v in combo:
                deg[u] += 1
                deg[v] += 1
            if all(d >= 3 for d in deg.values()):
                print(f"Found with {r} additional edges: {combo}")
                found = True
                break
        if r > 10:  # limit search
            break
    if not found:
        print("No solution found in limited search")
